function owner(doc){let win=doc.defaultView;try{while(win.parent!==win&&win.parent.document)win=win.parent;}catch{}return win;}
const OWNED='.phone16-root,.dn-window,.sb-window,.routine-scene,.collection-window,.fw-host,.scene-phone-cluster,.floating-surface,.location-window,.dd-window,.cs-window,.np-window,.rg-window';
